    /** 1.20.x DrawContext.method_48587 */
    @SuppressWarnings({"unchecked", "unused"})
    public void method_48587(net.minecraft.resources.Identifier tex, int x, int y, int w, int h, int left, int top, int right, int bottom, int regionW, int regionH, int u, int v) {
        if (w == regionW && h == regionH) { ext.blit(net.minecraft.client.renderer.RenderPipelines.GUI_TEXTURED, tex, x, y, (float) u, (float) v, w, h, 256, 256); return; }
        // corners
        ext.blit(net.minecraft.client.renderer.RenderPipelines.GUI_TEXTURED, tex, x, y, (float) u, (float) v, left, top, 256, 256);
        ext.blit(net.minecraft.client.renderer.RenderPipelines.GUI_TEXTURED, tex, x + w - right, y, (float) (u + regionW - right), (float) v, right, top, 256, 256);
        ext.blit(net.minecraft.client.renderer.RenderPipelines.GUI_TEXTURED, tex, x, y + h - bottom, (float) u, (float) (v + regionH - bottom), left, bottom, 256, 256);
        ext.blit(net.minecraft.client.renderer.RenderPipelines.GUI_TEXTURED, tex, x + w - right, y + h - bottom, (float) (u + regionW - right), (float) (v + regionH - bottom), right, bottom, 256, 256);
        // edges, tiled
        tile(tex, x + left, y, w - left - right, top, u + left, v, regionW - left - right, top);
        tile(tex, x + left, y + h - bottom, w - left - right, bottom, u + left, v + regionH - bottom, regionW - left - right, bottom);
        tile(tex, x, y + top, left, h - top - bottom, u, v + top, left, regionH - top - bottom);
        tile(tex, x + w - right, y + top, right, h - top - bottom, u + regionW - right, v + top, right, regionH - top - bottom);
        // center
        tile(tex, x + left, y + top, w - left - right, h - top - bottom, u + left, v + top, regionW - left - right, regionH - top - bottom);
    }

